// ── G-Counter: grow-only distributed counter ──────────────────
class GCounter {
  constructor(nodeId) {
    this.nodeId = nodeId;
    this.slots = { [nodeId]: 0 };
  }

  increment(amount = 1) {
    this.slots[this.nodeId] = (this.slots[this.nodeId] || 0) + amount;
  }

  value() {
    return Object.values(this.slots).reduce((sum, v) => sum + v, 0);
  }

  // State-based merge: component-wise maximum
  // Commutative, associative, idempotent — guarantees convergence
  merge(otherSlots) {
    for (const [node, count] of Object.entries(otherSlots)) {
      this.slots[node] = Math.max(this.slots[node] || 0, count);
    }
  }
}

// Demonstrate convergence regardless of sync order
const nodeA = new GCounter('A');
const nodeB = new GCounter('B');

nodeA.increment(3); // A does 3 increments
nodeB.increment(2); // B does 2 increments

// Scenario 1: A syncs to B first, then B syncs back
nodeB.merge(nodeA.slots);  // B merges A's state
nodeA.merge(nodeB.slots);  // A merges B's state (which already has A's)
console.log('A value:', nodeA.value()); // 5
console.log('B value:', nodeB.value()); // 5

// Scenario 2: Idempotency — merging same state twice is safe
nodeA.merge(nodeB.slots);
console.log('A after double merge:', nodeA.value()); // still 5

// ── PN-Counter: supports both increment and decrement ─────────
class PNCounter {
  constructor(nodeId) {
    this.nodeId = nodeId;
    this.P = new GCounter(nodeId); // increments
    this.N = new GCounter(nodeId); // decrements
  }

  increment(amount = 1) { this.P.increment(amount); }
  decrement(amount = 1) { this.N.increment(amount); }
  value() { return this.P.value() - this.N.value(); }

  merge(other) {
    this.P.merge(other.P.slots);
    this.N.merge(other.N.slots);
  }
}

const inv1 = new PNCounter('node1');
const inv2 = new PNCounter('node2');

inv1.increment(10); // add 10 units to inventory
inv2.decrement(3);  // sell 3 units concurrently

inv1.merge(inv2);   // sync
inv2.merge(inv1);   // sync

console.log('Inventory:', inv1.value()); // 7 — correct regardless of order

// ── OR-Set: add/remove set with conflict-free re-addition ─────
const { randomUUID } = require('crypto');

class ORSet {
  constructor() {
    // element -> Set of live tags
    this.entries = new Map();
    // Set of tombstoned tags
    this.tombstones = new Set();
  }

  add(element) {
    const tag = randomUUID(); // globally unique — never collides
    if (!this.entries.has(element)) this.entries.set(element, new Set());
    this.entries.get(element).add(tag);
    return tag; // in op-based variant, broadcast (ADD, element, tag)
  }

  remove(element) {
    // Tombstone ALL current tags for this element
    // Future adds will have new tags — they survive
    const tags = this.entries.get(element);
    if (tags) tags.forEach(tag => this.tombstones.add(tag));
  }

  has(element) {
    const tags = this.entries.get(element);
    if (!tags) return false;
    // Element is live if at least one tag is not tombstoned
    return [...tags].some(tag => !this.tombstones.has(tag));
  }

  // State-based merge: union entries, union tombstones
  merge(other) {
    for (const [element, tags] of other.entries) {
      if (!this.entries.has(element)) this.entries.set(element, new Set());
      const myTags = this.entries.get(element);
      tags.forEach(tag => myTags.add(tag));
    }
    other.tombstones.forEach(tag => this.tombstones.add(tag));
  }
}

// Concurrent add-remove scenario
const replicaA = new ORSet();
const replicaB = new ORSet();

// Both replicas start with apple (tag1 seen by both)
const tag1 = replicaA.add('apple');
// Propagate initial add to B
replicaB.merge(replicaA);

// Now concurrent: B removes apple, A re-adds apple — both offline
replicaB.remove('apple');       // tombstones tag1
const tag2 = replicaA.add('apple'); // adds tag2 (new UUID)

// After reconnect — both sync
replicaA.merge(replicaB);
replicaB.merge(replicaA);

// Result: apple has tag1 (tombstoned) and tag2 (live)
console.log('A has apple?', replicaA.has('apple')); // true — tag2 survives
console.log('B has apple?', replicaB.has('apple')); // true — same after merge
